      de: ["Erster Nationalpark in Nordmazedonien", "Gegründet 1948", "Zwei Gletscherseen (Pelister-Augen)", "Seltener fünfadeliger Kiefer"],
      hu: ["Az első nemzeti park Észak-Macedóniában", "1948-ban alapították", "Két gleccsertó (Peliszter-szemek)", "Ritka öttűs fenyő"],
