    imageHint: "pelister mountain glacial lake",
    descriptionAdvanced: {
      de: "Der Nationalpark Pelister befindet sich im Baba-Gebirge im Südwesten Nordmazedoniens nahe der Stadt Bitola. Er wurde 1948 als erster Nationalpark im ehemaligen Jugoslawien gegründet und umfasst heute eine Fläche von rund 171 Quadratkilometern. Bekannt ist der Park vor allem für die Molika-Kiefer (Pinus peuce), eine fünf-nadelige Kiefernart, die als Relikt aus der Tertiärzeit gilt und hier große, unberührte Bestände bildet. Der höchste Gipfel, der Pelister, ragt 2601 Meter in die Höhe und ist durch alpine Vegetation und markante Felsformationen gekennzeichnet. Ein besonderes geografisches Merkmal sind die 'Pelister-Augen', zwei gletschergeformte Seen in großer Höhe, die als Großer und Kleiner See bekannt sind. Die Tierwelt umfasst Braunbären, Wölfe und den seltenen Pelister-Bachforellen-Endemiten, was die Region zu einem bedeutenden Zentrum für den Naturschutz in Südosteuropa macht.",
      hu: "A Pelister Nemzeti Park a Baba-hegységben található Észak-Macedónia délnyugati részén, Bitola városa közelében. 1948-ban alapították, ezzel ez volt az egykori Jugoszlávia legelső nemzeti parkja; területe ma mintegy 171 négyzetkilométer. A park legfőbb jellegzetessége a balkáni selyemfenyő (Pinus peuce), egy öttűs fenyőfaj, amely a harmadidőszakból maradt ránk, és itt alkotja legszebb állományait. Legmagasabb csúcsa, a Pelister, 2601 méter magasra nyúlik, felszínét alpesi vegetáció és látványos kőfolyások borítják. Különleges földrajzi képződményei a 'Pelister szemei' néven ismert gleccsertavak, a Nagy-tó és a Kis-tó, amelyek 2218, illetve 2180 méteres magasságban fekszenek. Az állatvilág olyan fajokat foglal magában, mint a barna medve, a farkas és a ritka Pelister-sebespisztráng, kiemelve a régió természetvédelmi fontosságát.",
      ro: "Parcul Național Pelister este situat în masivul muntos Baba din sud-vestul Macedoniei de Nord, în apropierea orașului Bitola. Fondat în 1948, acesta a fost primul parc național din fosta Iugoslavie, întinzându-se în prezent pe o suprafață de circa 171 de kilometri pătrați. Parcul este celebru pentru pinul Molika (Pinus peuce), o specie de pin cu cinci ace care reprezintă un vestigiu din perioada terțiară și formează aici păduri vaste și virgine. Cel mai înalt vârf, Pelister, atinge 2601 metri și este caracterizat de vegetație alpină și formațiuni stâncoase deosebite. O trăsătură geografică distinctă sunt 'Ochii Pelisterului', două lacuri glaciare situate la altitudini mari, cunoscute sub numele de Lacul Mare și Lacul Mic. Fauna include ursul brun, lupu și păstrăvul de munte endemic de Pelister, transformând regiunea într-un centru vital pentru conservarea naturii în Europa de Sud-Est.",
      en: "Pelister National Park is located within the Baba Mountain range in southwestern North Macedonia, near the city of Bitola. Established in 1948, it was the first national park in the former Yugoslavia and currently encompasses an area of approximately 171 square kilometers. The park is renowned for the Molika pine (Pinus peuce), a five-needle pine species that is a relic of the Tertiary period and forms expansive, pristine forests here. Its highest peak, Pelister, reaches an elevation of 2,601 meters and is defined by alpine vegetation and unique rock rivers composed of granite blocks. A prominent geographical feature is the 'Pelister Eyes', two glacial lakes located at high altitudes known as the Big and Small Lake. The wildlife includes brown bears, wolves, and the rare endemic Pelister trout, making the region a significant center for biodiversity and conservation in Southeast Europe.",
      es: "El Parque Nacional Pelister en Macedonia del Norte se encuentra en las montañas Baba, cerca de la ciudad de Bitola. Fundado en 1948 como el primer parque nacional del país, abarca una superficie de 125 kilómetros cuadrados. El pico más alto es el Pelister con 2.601 metros. El parque es conocido por sus cinco lagos glaciares situados a 2.000 metros de altitud. La flora incluye el pino Molika endémico. La fauna incluye osos, gamuzas y águilas reales. El parque ofrece senderos y esquí en invierno. El clima es alpino.",
      pt: "O Parque Nacional Pelister, na Macedónia do Norte, situa-se nas montanhas Baba, perto da cidade de Bitola. Fundado em 1948 como o primeiro parque nacional do país, abrange uma área de 125 quilómetros quadrados. O pico mais alto é o Pelister, com 2.601 metros. O parque é conhecido pelos seus cinco lagos glaciares, situados a 2.000 metros de altitude. A flora inclui o pinheiro Molika endémico. A fauna inclui ursos, camurças e águias-reais. O parque oferece trilhos para caminhadas e esqui no inverno. O clima é alpino.",
      fr: "Le parc national de Pelister, en Macédoine du Nord, est situé dans les monts Baba, à proximité de Bitola. Fondé en 1948, il fut le premier parc national du pays et couvre 125 kilomètres carrés. Le sommet culminant est le Pelister, à 2 601 mètres. Le parc est réputé pour ses cinq lacs glaciaires perchés à 2 000 mètres d'altitude. La flore comprend le pin Molika, une espèce endémique. La faune compte des ours, des chamois et des aigles royaux. Le parc propose des sentiers de randonnée et du ski en hiver. Le climat y est alpin.",
    },
    factsAdvanced: {
      de: ["Pelister wurde 1948 zum ersten Nationalpark des Balkans erklärt.", "Die Molika-Kiefer kann ein Alter von über 200 Jahren erreichen.", "Der Große See liegt auf einer beeindruckenden Höhe von 2218 Metern.", "Die Granit-Steinpfade im Park entstanden durch periglaziale Prozesse.", "Der Pelister-Gipfel ist mit 2601 Metern die höchste Erhebung des Baba-Massivs.", "Im Park leben über 10 Brutpaare des seltenen Steinadlers."],
      hu: ["Pelister volt a Balkán első kijelölt nemzeti parkja 1948-ban.", "A balkáni selyemfenyő (Molika) példányai akár 200 évnél is tovább élhetnek.", "A Nagy-tó 2218 méteres tengerszint feletti magasságban található.", "A park híres kőfolyásait a jégkorszaki fagyaprózódás alakította ki.", "A 2601 méter magas Pelister-csúcs a Baba-hegység legmagasabb pontja.", "A területen fészkel a ritka szirti sas is, amely szigorúan védett."],
      ro: ["Pelister a devenit primul parc național de pe teritoriul Balcanilor în 1948.", "Pinul Molika poate atinge o vârstă venerabilă de peste 200 de ani.", "Lacul Mare (Big Lake) este situat la o altitudine de 2218 metri.", "Ghețarii din trecut au lăsat în urmă 'râuri de piatră' din blocuri de granit.", "Vârful Pelister atinge altitudinea maximă de 2601 metri în masivul Baba.", "Parcul adăpostește populații stabile de acvile de munte."],
      en: ["Pelister was declared the first national park in the Balkans in 1948.", "Individual Molika pines can live for more than 200 years.", "The Big Lake is situated at a notable altitude of 2,218 meters.", "The park's famous 'rock rivers' were formed by periglacial weathering.", "Pelister Peak is the highest point of the Baba massif at 2,601 meters.", "The area is home to nesting pairs of the rare golden eagle."],
      es: ["Primer parque nacional de Macedonia del Norte, fundado en 1948.", "Superficie: 125 km².", "Pico más alto: 2.601 metros.", "Cinco lagos glaciares, el mayor tiene 200 metros de largo.", "El pino Molika puede vivir hasta 500 años.", "El parque alberga más de 80 especies de aves."],
      pt: ["Primeiro parque nacional da Macedónia do Norte, fundado em 1948.", "Área: 125 km².", "Pico mais alto: 2.601 metros.", "Cinco lagos glaciares, o maior tem 200 metros de comprimento.", "O pinheiro Molika pode viver até 500 anos.", "O parque alberga mais de 80 espécies de aves."],
      fr: ["Premier parc national de Macédoine du Nord, fondé en 1948.", "Superficie : 125 km².", "Sommet le plus élevé : 2 601 mètres.", "Cinq lacs glaciaires, le plus grand mesure 200 mètres.", "Le pin Molika peut vivre jusqu'à 500 ans.", "Le parc abrite plus de 80 espèces d'oiseaux."],
    },
