    imageHint: "dense forest canopy in koprivnica",
    descriptionAdvanced: {
      de: "Der Koprivnica-Wald erstreckt sich im Osten Nordmazedoniens nahe der Stadt Pehčevo in den Maleševo-Bergen. Dieses dichte Waldgebiet ist vor allem für seine beeindruckenden Bestände an Rotbuchen und Kiefern bekannt, die eine wichtige ökologische Lunge für die Region bilden. Ein besonderes Merkmal des Gebiets sind die sieben Pehčevo-Wasserfälle, die entlang der Nebenflüsse der Bregalnica in kaskadenförmigen Stufen herabstürzen. In der Nähe befindet sich der Standort Judovi Livadi, wo die seltene fleischfressende Pflanze Drosera rotundifolia vorkommt. Das Ökosystem bietet Lebensraum für zahlreiche Wildtierarten wie Wildschweine, Rehe und verschiedene Greifvögel. Historisch gesehen war die Region während der osmanischen Zeit ein wichtiges Zentrum für die Holzgewinnung und Harzproduktion. Heute steht der Schutz der Wasserressourcen und der Erhalt der alpinen Biodiversität im Vordergrund der lokalen Forstwirtschaft.",
      hu: "A Koprivnica-erdő Észak-Macedónia keleti részén, Pehčevo városa közelében, a Maleševo-hegységben található. Ez a sűrű erdőség elsősorban őshonos bükk- és fenyőállományairól nevezetes, amelyek fontos ökológiai folyosót alkotnak a régióban. A terület egyik leglátványosabb jellemzője a hét pehčevói vízesés, amelyek a Bregalnica-folyó mellékágain, különböző magasságokban zúdulnak alá. A közelben található Judovi Livadi lápvidéke, amely a ritka húsevő növény, a kereklevelű harmatfű (Drosera rotundifolia) egyik utolsó menedékhelye a Balkánon. Az erdő gazdag faunájának részét képezik a vaddisznók, őzek és számos hegyvidéki madárfaj, amelyek a háborítatlan vadonban találnak otthonra. Történelmileg a környék a fafeldolgozásáról és gyantatermeléséről volt híres, ma azonban a hangsúly a természetvédelemre és a vízgyűjtő területek megőrzésére helyeződött át.",
      ro: "Pădurea Koprivnica este situată în partea de est a Macedoniei de Nord, în apropierea orașului Pehčevo, în Munții Maleševo. Această zonă forestieră densă este compusă în principal din exemplare vechi de fag și pin, reprezentând un plămân verde esențial pentru ecosistemul regional. Regiunea este celebră pentru cele șapte cascade de lângă Pehčevo, care se formează pe afluenții râului Bregalnica în trepte spectaculoase. Un aspect biologic remarcabil este situl Judovi Livadi, unde poate fi găsită planta carnivoră rară Drosera rotundifolia. Pădurea oferă un habitat critic pentru diverse specii de animale sălbatice, inclusiv mistreți, căprioare și numeroase păsări de munte. Din punct de vedere istoric, zona a fost un centru important pentru producția de cherestea și rășină în perioada otomană. În prezent, conservarea biodiversității și protejarea resurselor de apă sunt prioritățile principale ale managementului forestier local.",
      en: "The Koprivnica Forest is situated in the eastern part of North Macedonia, near the town of Pehčevo in the Maleševo Mountains. This dense woodland area is predominantly composed of ancient beech and pine trees, forming a vital ecological corridor in the region. The area is renowned for its hydrological wealth, featuring seven distinct waterfalls located along the course of the Bregalnica River's tributaries. One of the most significant biological features is the nearby Judovi Livadi site, which hosts the rare insectivorous plant Drosera rotundifolia. The forest provides a critical habitat for various mountain fauna, including wild boars, roe deer, and numerous bird species. Historically, the region was an important center for timber and resin production during the Ottoman period. Today, it serves as a key ecological zone for the protection of water resources and the preservation of alpine biodiversity in the eastern Balkans.",
      es: "El bosque de Koprivnica en Macedonia del Norte se encuentra cerca de la ciudad de Kratovo, en el noreste del país. Es un área boscosa densa que consiste principalmente en hayas y robles. El bosque forma parte del monte Osogovo. Es conocido por su biodiversidad y sirve como hábitat para ciervos, jabalíes y diversas especies de aves. El bosque es un destino popular para recolectores de setas y senderistas. La región también es conocida por la minería, con minas históricas en las cercanías. El bosque se extiende por unos 50 kilómetros cuadrados.",
      pt: "A floresta de Koprivnica, na Macedônia do Norte, situa-se perto da cidade de Kratovo, no nordeste do país. É uma área florestal densa, consistindo principalmente em faias e carvalhos. A floresta faz parte do monte Osogovo. É conhecida pela sua biodiversidade e serve de habitat para veados, javalis e várias espécies de aves. A floresta é um destino popular para coletores de cogumelos e caminhantes. A região também é conhecida pela mineração, com minas históricas nas proximidades. A floresta estende-se por cerca de 50 quilômetros quadrados.",
      fr: "La forêt de Koprivnica en Macédoine du Nord se situe près de la ville de Kratovo, dans le nord-est du pays. C'est un massif forestier dense, composé essentiellement de hêtres et de chênes. La forêt fait partie du mont Osogovo. Elle est réputée pour sa biodiversité et sert d'habitat aux cerfs, aux sangliers et à diverses espèces d'oiseaux. La forêt est une destination prisée des ramasseurs de champignons et des randonneurs. La région est également connue pour son activité minière, avec des mines historiques à proximité. La forêt couvre environ 50 kilomètres carrés.",
    },
    factsAdvanced: {
      de: ["Beheimatet 7 verschiedene Wasserfälle in der Nähe von Pehčevo.", "Standort der seltenen fleischfressenden Pflanze Drosera rotundifolia.", "Gehört zum Maleševo-Gebirgszug an der bulgarischen Grenze.", "Besteht überwiegend aus Kiefern- und Buchenmischwäldern.", "Wichtiges Quellgebiet für Nebenflüsse der Bregalnica.", "Liegt auf einer durchschnittlichen Höhe von etwa 1000 Metern."],
      hu: ["A Pehčevo környéki 7 vízesésnek ad otthont.", "Itt található a Drosera rotundifolia húsevő növény ritka állománya.", "A bolgár határ menti Maleševo-hegység része.", "Az erdőtúlnyomó részt fenyő és bükk alkotja.", "A Bregalnica folyó mellékágainak fontos vízgyűjtője.", "Az átlagos tengerszint feletti magassága 1000 méter körül mozog."],
      ro: ["Găzduiește cele 7 cascade celebre de lângă Pehčevo.", "Include situl Judovi Livadi cu planta carnivoră Drosera rotundifolia.", "Face parte din lanțul muntos Maleševo de la granița cu Bulgaria.", "Compoziția dominantă este formată din păduri de pin și fag.", "Zonă crucială de captare pentru afluenții râului Bregalnica.", "Altitudinea medie a pădurii este de aproximativ 1000 de metri."],
      en: ["Home to 7 distinct waterfalls located near Pehčevo.", "Hosts the rare insectivorous plant Drosera rotundifolia.", "Part of the Maleševo mountain range along the Bulgarian border.", "Predominantly composed of pine and beech forest stands.", "Critical watershed area for tributaries of the Bregalnica River.", "Situated at an average elevation of approximately 1000 meters."],
      es: ["Superficie: 50 km².", "El punto más alto del bosque está a 1.200 metros.", "El bosque alberga 150 especies de plantas.", "Las copas de los árboles cubren el 90 % del bosque.", "La precipitación media es de 600 mm anuales.", "Hay 20 km de senderos señalizados en el bosque."],
      pt: ["Área: 50 km².", "O ponto mais alto da floresta situa-se a 1.200 metros.", "A floresta abriga 150 espécies de plantas.", "As copas das árvores cobrem 90% da floresta.", "A precipitação média é de 600 mm por ano.", "Existem 20 km de trilhas sinalizadas na floresta."],
      fr: ["Superficie : 50 km².", "Le point culminant de la forêt se situe à 1 200 mètres.", "La forêt abrite 150 espèces végétales.", "La canopée couvre 90 % de la forêt.", "La pluviométrie moyenne est de 600 mm par an.", "La forêt compte 20 km de sentiers de randonnée balisés."],
    },
