    imageHint: "small island in lake ohrid",
    descriptionAdvanced: {
      de: "Die Ostrovo-Insel ist eine kleine Insel im Prespa-See im Südwesten Nordmazedoniens. Sie hat eine Fläche von etwa 0,3 Quadratkilometern und ist die einzige bewohnte Insel des Landes. Die Insel ist bekannt für ihre byzantinische Kirche aus dem 14. Jahrhundert, die dem Heiligen Georg geweiht ist. Die Vegetation besteht aus mediterranen Sträuchern und Kiefern. Die Insel beherbergt eine Kolonie von Kormoranen und anderen Wasservögeln. Historisch war die Insel ein wichtiger Zufluchtsort während der osmanischen Herrschaft, und die Kirche diente als kulturelles Zentrum. Der Name 'Ostrovo' leitet sich vom slawischen Wort für 'Insel' ab. Der See selbst ist einer der ältesten Süßwasserseen Europas und liegt auf einer Höhe von 853 Metern. Die Insel ist nur mit dem Boot erreichbar und ein beliebtes Ziel für Touristen und Pilger.",
      hu: "Az Ostrovo-sziget egy kis sziget a Prespa-tóban, Észak-Macedónia délnyugati részén. Területe körülbelül 0,3 négyzetkilométer, és ez az ország egyetlen lakott szigete. A sziget híres a 14. századi bizánci templomáról, amelyet Szent György tiszteletére szenteltek. A növényzet mediterrán cserjékből és fenyőkből áll. A szigeten kormoránok és más vízimadarak telepei találhatók. Történelmileg a sziget fontos menedékhely volt a török uralom alatt, és a templom kulturális központként szolgált. Az 'Ostrovo' név a szláv 'sziget' szóból származik. A tó Európa egyik legrégebbi édesvizű tava, 853 méter tengerszint feletti magasságban fekszik. A sziget csak csónakkal érhető el, és népszerű turisztikai és zarándokcélpont.",
      ro: "Insula Ostrovo este o mică insulă din Lacul Prespa, în sud-vestul Macedoniei de Nord. Are o suprafață de aproximativ 0,3 kilometri pătrați și este singura insulă locuită din țară. Insula este cunoscută pentru biserica sa bizantină din secolul al XIV-lea, dedicată Sfântului Gheorghe. Vegetația constă în tufișuri mediteraneene și pini. Insula adăpostește o colonie de cormorani și alte păsări acvatice. Din punct de vedere istoric, insula a fost un important refugiu în timpul dominației otomane, iar biserica a servit ca centru cultural. Numele 'Ostrovo' provine din slavona pentru 'insulă'. Lacul este unul dintre cele mai vechi lacuri de apă dulce din Europa, situat la o altitudine de 853 de metri. Insula este accesibilă doar cu barca și este o destinație populară pentru turiști și pelerini.",
      en: "Ostrovo Island is a small island in Lake Prespa, southwestern North Macedonia. It covers about 0.3 square kilometers and is the country's only inhabited island. The island is known for its 14th-century Byzantine church dedicated to Saint George. Vegetation includes Mediterranean shrubs and pines. The island hosts a colony of cormorants and other waterbirds. Historically, the island was an important refuge during Ottoman rule, and the church served as a cultural center. The name 'Ostrovo' derives from the Slavic word for 'island'. The lake is one of Europe's oldest freshwater lakes, at an altitude of 853 meters. The island is only accessible by boat and is a popular destination for tourists and pilgrims.",
      es: "La isla de Ostrovo es una pequeña masa de tierra situada en el lago Prespa, al suroeste de Macedonia del Norte. Con una superficie de unos 0,3 kilómetros cuadrados, es la única isla habitada del país. Es famosa por su iglesia bizantina del siglo XIV, dedicada a San Jorge. La vegetación consiste en arbustos mediterráneos y pinos, albergando una colonia de cormoranes y otras aves acuáticas. Históricamente, la isla fue un refugio importante durante el dominio otomano y la iglesia sirvió como centro cultural. El nombre \"Ostrovo\" proviene de la palabra eslava para \"isla\". El lago es uno de los lagos de agua dulce más antiguos de Europa y se encuentra a una altitud de 853 metros. Solo es accesible en barco y es un destino popular para turistas y peregrinos.",
      pt: "A ilha de Ostrovo é uma pequena ilha no lago Prespa, no sudoeste da Macedónia do Norte. Tem uma área de cerca de 0,3 quilómetros quadrados e é a única ilha habitada do país. A ilha é conhecida pela sua igreja bizantina do século XIV, dedicada a São Jorge. A vegetação é composta por arbustos mediterrânicos e pinheiros. A ilha alberga uma colónia de cormorões e outras aves aquáticas. Historicamente, a ilha foi um importante refúgio durante o domínio otomano e a igreja serviu como centro cultural. O nome \"Ostrovo\" deriva da palavra eslava para \"ilha\". O próprio lago é um dos lagos de água doce mais antigos da Europa e situa-se a uma altitude de 853 metros. A ilha só é acessível por barco e é um destino popular para turistas e peregrinos.",
      fr: "L'île d'Ostrovo est une petite île du lac Prespa, dans le sud-ouest de la Macédoine du Nord. Elle s'étend sur environ 0,3 kilomètre carré et constitue la seule île habitée du pays. L'île est réputée pour son église byzantine du XIVe siècle, dédiée à Saint-Georges. La végétation se compose d'arbustes méditerranéens et de pins. L'île abrite une colonie de cormorans et d'autres oiseaux aquatiques. Historiquement, l'île fut un refuge important sous la domination ottomane, et l'église servait de centre culturel. Le nom \"Ostrovo\" provient du mot slave signifiant \"île\". Le lac lui-même est l'un des plus anciens lacs d'eau douce d'Europe, situé à 853 mètres d'altitude. L'île n'est accessible que par bateau et représente une destination prisée des touristes et des pèlerins.",
    },
    factsAdvanced: {
      de: ["Die Insel hat eine Fläche von 0,3 km².", "Die Kirche Sveti Gjorgji wurde im 14. Jahrhundert erbaut.", "Die Insel liegt auf 848 m über dem Meeresspiegel.", "Der Prespa-See ist etwa 4,5 Millionen Jahre alt.", "Auf der Insel leben etwa 10 ständige Einwohner.", "Die Kormoran-Kolonie umfasst etwa 200 Brutpaare."],
      hu: ["A sziget területe 0,3 km².", "A Sveti Gjorgji templom a 14. században épült.", "A sziget tengerszint feletti magassága 848 m.", "A Prespa-tó körülbelül 4,5 millió éves.", "A szigeten körülbelül 10 állandó lakos él.", "A kormorán-telep körülbelül 200 költőpárból áll."],
      ro: ["Insula are o suprafață de 0,3 km².", "Biserica Sveti Gjorgji a fost construită în secolul al XIV-lea.", "Insula se află la o altitudine de 848 m.", "Lacul Prespa are aproximativ 4,5 milioane de ani.", "Pe insulă trăiesc aproximativ 10 locuitori permanenți.", "Colonia de cormorani numără circa 200 de perechi cuibăritoare."],
      en: ["The island has an area of 0.3 km².", "Sveti Gjorgji Church was built in the 14th century.", "The island lies at 848 m above sea level.", "Lake Prespa is about 4.5 million years old.", "About 10 permanent residents live on the island.", "The cormorant colony numbers about 200 breeding pairs."],
      es: ["La isla tiene una superficie de 0,3 km².", "La iglesia Sveti Gjorgji fue construida en el siglo XIV.", "La isla se encuentra a 848 m sobre el nivel del mar.", "El lago Prespa tiene unos 4,5 millones de años.", "En la isla viven unos 10 habitantes permanentes.", "La colonia de cormoranes incluye unas 200 parejas reproductoras."],
      pt: ["A ilha tem uma área de 0,3 km².", "A igreja Sveti Gjorgji foi construída no século XIV.", "A ilha situa-se a 848 m acima do nível do mar.", "O lago Prespa tem cerca de 4,5 milhões de anos.", "Cerca de 10 habitantes permanentes vivem na ilha.", "A colónia de cormorões inclui cerca de 200 casais reprodutores."],
      fr: ["L'île a une superficie de 0,3 km².", "L'église Sveti Gjorgji a été construite au XIVe siècle.", "L'île est située à 848 m au-dessus du niveau de la mer.", "Le lac Prespa est âgé d'environ 4,5 millions d'années.", "Environ 10 habitants permanents vivent sur l'île.", "La colonie de cormorans comprend environ 200 couples nicheurs."],
    },
