    imageHint: "pcinja river valley scenery",
    descriptionAdvanced: {
      de: "Das Pcinja-Tal liegt im Süden Nordmazedoniens und erstreckt sich entlang des gleichnamigen Flusses, der in die Vardar mündet. Das Tal ist etwa 50 Kilometer lang und bekannt für seine fruchtbaren Böden, die den Anbau von Getreide, Obst und Gemüse ermöglichen. Die Region ist dünn besiedelt mit kleinen Dörfern, die traditionelle Lebensweisen bewahren. Der Fluss Pcinja ist ein wichtiger Nebenfluss des Vardar und bietet Lebensraum für Fischotter und verschiedene Vogelarten. Das Tal beherbergt mehrere archäologische Stätten, darunter die römische Siedlung 'Pcinja' aus dem 2. Jahrhundert nach Christus. Die Landschaft ist geprägt von sanften Hügeln und Auwäldern. Die Wirtschaft ist hauptsächlich landwirtschaftlich geprägt, mit Schwerpunkt auf Weinbau und Tabakanbau. Das Tal ist auch für seine Thermalquellen bekannt, wie die bei der Stadt Strumica.",
      hu: "A Pcinja-völgy Észak-Macedónia déli részén húzódik a Pcinja folyó mentén, amely a Vardarba ömlik. A völgy körülbelül 50 km hosszú, termékeny talajáról ismert, amely lehetővé teszi gabona, gyümölcs és zöldség termesztését. A régió ritkán lakott, kis falvakkal, amelyek megőrizték a hagyományos életmódot. A Pcinja folyó a Vardar fontos mellékfolyója, élőhelyet biztosít a vidráknak és különféle madárfajoknak. A völgyben több régészeti lelőhely található, köztük a 2. századi római település, 'Pcinja'. A tájat enyhe dombok és ártéri erdők jellemzik. A gazdaság főként mezőgazdasági, a szőlő- és dohánytermesztésre összpontosítva. A völgy termálforrásairól is ismert, például a Strumica város közelében találhatóak.",
      ro: "Valea Pcinja este situată în sudul Macedoniei de Nord, de-a lungul râului Pcinja, care se varsă în Vardar. Valea are aproximativ 50 de kilometri lungime și este cunoscută pentru solurile sale fertile, care permit cultivarea cerealelor, fructelor și legumelor. Regiunea este slab populată, cu sate mici care păstrează moduri de viață tradiționale. Râul Pcinja este un afluent important al Vardarului, oferind habitat pentru vidre și diverse specii de păsări. Valea adăpostește mai multe situri arheologice, inclusiv așezarea romană 'Pcinja' din secolul al II-lea d.Hr. Peisajul constă în dealuri line și păduri de luncă. Economia este predominant agricolă, cu accent pe viticultură și cultivarea tutunului. Valea este cunoscută și pentru izvoarele sale termale, precum cele de lângă orașul Strumica.",
      en: "The Pcinja Valley is in southern North Macedonia, along the Pcinja River, a tributary of the Vardar. The valley is about 50 kilometers long, known for its fertile soils that support grain, fruit, and vegetable cultivation. The region is sparsely populated with small villages preserving traditional lifestyles. The Pcinja River provides habitat for otters and various bird species. The valley hosts several archaeological sites, including the Roman settlement 'Pcinja' from the 2nd century AD. The landscape features gentle hills and riparian forests. The economy is primarily agricultural, focusing on viticulture and tobacco farming. The valley is also known for its thermal springs, such as those near Strumica.",
      es: "El valle del Pcinja se encuentra en el sur de Macedonia del Norte y se extiende a lo largo del río homónimo, que desemboca en el Vardar. El valle tiene unos 50 kilómetros de largo y es conocido por sus suelos fértiles, que permiten el cultivo de cereales, frutas y verduras. La región está escasamente poblada con pequeños pueblos que conservan formas de vida tradicionales. El río Pcinja es un afluente importante del Vardar y ofrece hábitat para nutrias y varias especies de aves. El valle alberga varios sitios arqueológicos, incluido el asentamiento romano de \"Pcinja\" del siglo II d.C. El paisaje se caracteriza por colinas suaves y bosques de ribera. La economía es principalmente agrícola, con énfasis en la viticultura y el cultivo de tabaco. El valle también es conocido por sus fuentes termales, como las cercanas a la ciudad de Strumica.",
      pt: "O vale do Pcinja situa-se no sul da Macedónia do Norte e estende-se ao longo do rio com o mesmo nome, que desagua no Vardar. O vale tem cerca de 50 quilómetros de comprimento e é conhecido pelos seus solos férteis, que permitem o cultivo de cereais, frutas e legumes. A região é pouco povoada, com pequenas aldeias que preservam modos de vida tradicionais. O rio Pcinja é um importante afluente do Vardar e oferece habitat para lontras e várias espécies de aves. O vale alberga vários sítios arqueológicos, incluindo o povoado romano de \"Pcinja\" do século II d.C. A paisagem é caracterizada por colinas suaves e florestas de aluvião. A economia é maioritariamente agrícola, com destaque para a viticultura e a cultura do tabaco. O vale é também conhecido pelas suas águas termais, como as da cidade de Strumica.",
      fr: "La vallée de la Pcinja se situe dans le sud de la Macédoine du Nord et s'étend le long de la rivière éponyme, qui se jette dans le Vardar. Longue d'environ 50 kilomètres, la vallée est réputée pour ses sols fertiles permettant la culture de céréales, de fruits et de légumes. La région est peu peuplée, parsemée de petits villages préservant des modes de vie traditionnels. La rivière Pcinja, affluent majeur du Vardar, constitue un habitat pour la loutre et diverses espèces d'oiseaux. La vallée abrite plusieurs sites archéologiques, dont l'établissement romain de \"Pcinja\" datant du IIe siècle après J.-C. Le paysage est marqué par des collines douces et des forêts alluviales. L'économie est essentiellement agricole, centrée sur la viticulture et le tabac. La vallée est également connue pour ses sources thermales, comme celles situées près de la ville de Strumica.",
    },
    factsAdvanced: {
      de: ["Das Tal erstreckt sich über 50 km Länge.", "Die Breite des Tals beträgt durchschnittlich 5 km.", "Der Fluss Pcinja hat eine Länge von 65 km.", "Die römische Siedlung stammt aus dem 2. Jahrhundert n. Chr.", "Die jährliche Niederschlagsmenge liegt bei etwa 600 mm.", "Die Thermalquellen in Strumica haben eine Temperatur von 28 °C."],
      hu: ["A völgy hossza 50 km.", "A völgy átlagos szélessége 5 km.", "A Pcinja folyó hossza 65 km.", "A római település a 2. századból származik.", "Az éves csapadékmennyiség körülbelül 600 mm.", "A Strumicai termálforrások hőmérséklete 28 °C."],
      ro: ["Valea se întinde pe 50 km lungime.", "Lățimea medie a văii este de 5 km.", "Râul Pcinja are o lungime de 65 km.", "Așezarea romană datează din secolul al II-lea d.Hr.", "Precipitațiile anuale sunt de aproximativ 600 mm.", "Izvoarele termale de la Strumica au o temperatură de 28 °C."],
      en: ["The valley stretches over 50 km long.", "Average width of the valley is 5 km.", "The Pcinja River is 65 km long.", "The Roman settlement dates from the 2nd century AD.", "Annual precipitation is about 600 mm.", "Thermal springs at Strumica have a temperature of 28 °C."],
      es: ["El valle se extiende a lo largo de 50 km.", "La anchura del valle es de 5 km de media.", "El río Pcinja tiene una longitud de 65 km.", "El asentamiento romano data del siglo II d.C.", "La precipitación anual es de unos 600 mm.", "Las fuentes termales de Strumica tienen una temperatura de 28 °C."],
      pt: ["O vale estende-se por 50 km de comprimento.", "A largura do vale é de 5 km em média.", "O rio Pcinja tem uma extensão de 65 km.", "O povoado romano data do século II d.C.", "A precipitação anual é de cerca de 600 mm.", "As termas de Strumica têm uma temperatura de 28 °C."],
      fr: ["La vallée s'étend sur 50 km de long.", "La largeur moyenne de la vallée est de 5 km.", "La rivière Pcinja mesure 65 km de long.", "L'établissement romain date du IIe siècle apr. J.-C.", "Les précipitations annuelles sont d'environ 600 mm.", "Les sources thermales de Strumica atteignent 28 °C."],
    },
