      en: ["Largest glacial lake in the Šar Mountains range.", "Located at an altitude of 1936 meters.", "Maximum depth is approximately 2.2 meters.", "Feeds the flow of the Bogovinska Reka river.", "Covers an area of about 15,000 square meters.", "Formed during the Pleistocene glacial period."],
      es: ["El lago fue creado en 1972.", "La superficie del agua es de 1,2 km².", "La profundidad máxima es de 30 m.", "El lago almacena unos 10 millones de m³ de agua.", "La longitud de la orilla es de unos 8 km.", "La temperatura en verano alcanza una media de 22 °C."],
      pt: ["O lago foi criado em 1972.", "A superfície da água é de 1,2 km².", "A profundidade máxima é de 30 m.", "O lago armazena cerca de 10 milhões de m³ de água.", "A extensão da margem é de cerca de 8 km.", "A temperatura no verão atinge uma média de 22 °C."],
      fr: ["Le lac a été aménagé en 1972.", "La surface de l'eau est de 1,2 km².", "La profondeur maximale est de 30 m.", "Le lac stocke environ 10 millions de m³ d'eau.", "La longueur de la rive est d'environ 8 km.", "La température en été atteint en moyenne 22 °C."],
