      de: ["Der Fluss Bregalnica ist 80 km lang.", "Das Einzugsgebiet beträgt 1.500 km².", "Die jährliche Wasserführung beträgt etwa 15 m³/s.", "Die römischen Minen produzierten bis zu 5 Tonnen Gold pro Jahr.", "Die Stadt Probishtip liegt auf 600 m Höhe.", "Die Region hat eine Bevölkerung von rund 50.000 Menschen."],
