    imageHint: "dojran lake reed scenery",
    descriptionAdvanced: {
      de: "Das Dojran-Feuchtgebiet umfasst den südlichen Teil des Dojran-Sees, eines der drei tektonischen Seen Nordmazedoniens. Der See liegt auf 148 m Höhe und erstreckt sich über eine Fläche von 43,1 km², wovon 27,3 km² zu Nordmazedonien gehören. Das Feuchtgebiet ist ein wichtiger Rastplatz für Zugvögel entlang der Via Aristotelis und beherbergt über 200 Vogelarten, darunter seltene Pelikane und Reiher. Die Region ist bekannt für ihre Fischzucht, insbesondere den Dojran-Karpfen, der seit Jahrhunderten gefangen wird. Der See litt in den 1980er Jahren unter starkem Wasserverlust, was zu einem beispiellosen Artensterben führte. Dank internationaler Schutzmaßnahmen und Renaturierungsprojekten hat sich der Wasserstand teilweise erholt. Das Gebiet ist seit 2007 als Ramsar-Schutzgebiet ausgewiesen und zieht Ökotouristen an.",
      hu: "A Dojrán-tó és vizes élőhelye Észak-Macedónia délkeleti részén, a görög határ mentén terül el. A tó területe 43,1 km², maximális mélysége 10 méter. A vizes élőhely kiemelkedő madárvilággal rendelkezik: több mint 200 fajt regisztráltak, köztük a kis kárókatonát és a batla gólyát. A tó halászata évszázados hagyományokkal bír, de az 1980-as években a vízszint drasztikus csökkenése miatt a halállomány összeomlott. A 2000-es években megkezdett vízpótlási programok és a környezeti nevelés eredményeként a tó ökológiai állapota javult. A terület 2007-ben Ramsari egyezmény alá tartozó védett övezetté vált. A helyi közösségek a fenntartható turizmusban látják a jövőt, így madármegfigyelő tornyok és tanösvények épültek.",
      ro: "Zona umedă Dojran este situată în partea de sud-est a Macedoniei de Nord, la granița cu Grecia, și cuprinde Lacul Dojran. Lacul are o suprafață totală de 43,1 km² și o adâncime maximă de 10 m. Este un lac tectonic, cu o biodiversitate remarcabilă: peste 200 de specii de păsări, inclusiv pelicani creț și egrete. Clima mediteraneană influențează flora, cu specii precum stuful și nufărul galben. Din punct de vedere economic, pescuitul și turismul sunt principalele activități. În anii 1980, lacul a suferit o secetă severă din cauza extragerii excesive de apă pentru irigații, ceea ce a dus la dispariția multor specii de pești. Proiectele de restaurare, inclusiv aducția de apă de la râul Gjavato, au contribuit la refacerea parțială a ecosistemului. Zona umedă a fost declarată sit Ramsar în 2007.",
      en: "Dojran Wetland, situated on the border between North Macedonia and Greece, centers on Lake Dojran, a tectonic lake at 148 m elevation. The wetland covers approximately 30 km² of marshes, reed beds, and open water. It is a crucial stopover for migratory birds on the Adriatic Flyway, hosting over 200 species such as the Dalmatian pelican and the pygmy cormorant. The lake's fish fauna includes the endemic Dojran carp (Cyprinus carpio dojranensis). Historically, the lake supported a thriving fishing industry, but over-extraction for agriculture in the 20th century caused severe water level drops, reducing its area by half. Since the 1990s, restoration efforts including water diversion from the Crna River have stabilized the ecosystem. The wetland is a Ramsar site (designated 2007) and a Natura 2000 area, attracting eco-tourists. Its unique position in the Balkan Peninsula makes it a biodiversity hotspot for both aquatic and terrestrial species.",
      es: "El humedal de Dojran comprende la parte sur del lago Dojran, uno de los tres lagos tectónicos de Macedonia del Norte. El lago se encuentra a 148 m de altitud y cubre una superficie de 43,1 km², de los cuales 27,3 km² pertenecen a Macedonia del Norte. El humedal es un importante punto de descanso para las aves migratorias a lo largo de la Vía Aristotelis y alberga más de 200 especies de aves, incluyendo pelícanos y garzas raros. La región es conocida por su piscicultura, especialmente la carpa de Dojran, que se captura desde hace siglos. El lago sufrió una fuerte pérdida de agua en la década de 1980, lo que provocó una extinción de especies sin precedentes. Gracias a las medidas internacionales de protección y a los proyectos de renaturalización, el nivel del agua se ha recuperado parcialmente. El área está designada como sitio Ramsar desde 2007 y atrae a ecoturistas.",
      pt: "A zona úmida de Dojran abrange a parte sul do lago Dojran, um dos três lagos tectónicos da Macedónia do Norte. O lago situa-se a 148 m de altitude e estende-se por uma área de 43,1 km², dos quais 27,3 km² pertencem à Macedónia do Norte. A zona úmida é um importante local de descanso para aves migratórias ao longo da Via Aristotelis e abriga mais de 200 espécies de aves, incluindo pelicanos e garças raros. A região é conhecida pela sua piscicultura, especialmente a carpa de Dojran, que é capturada há séculos. O lago sofreu uma forte perda de água na década de 1980, o que levou a uma extinção de espécies sem precedentes. Graças a medidas internacionais de proteção e projetos de renaturalização, o nível da água recuperou parcialmente. A área está classificada como sítio Ramsar desde 2007 e atrai ecoturistas.",
      fr: "La zone humide de Dojran comprend la partie sud du lac Dojran, l'un des trois lacs tectoniques de Macédoine du Nord. Le lac est situé à 148 m d'altitude et s'étend sur une superficie de 43,1 km², dont 27,3 km² appartiennent à la Macédoine du Nord. La zone humide est une étape importante pour les oiseaux migrateurs le long de la Via Aristotelis et abrite plus de 200 espèces d'oiseaux, dont de rares pélicans et hérons. La région est réputée pour sa pisciculture, notamment la carpe de Dojran, pêchée depuis des siècles. Le lac a subi une forte baisse du niveau de ses eaux dans les années 1980, entraînant une extinction d'espèces sans précédent. Grâce aux mesures de protection internationales et aux projets de renaturation, le niveau de l'eau s'est partiellement rétabli. La zone est classée site Ramsar depuis 2007 et attire les écotouristes.",
    },
