      pt: ["Área do lago Dojran: 43,1 km² (total), dos quais 27,3 km² na Macedónia do Norte.", "Profundidade máxima: 10 metros.", "Altitude acima do nível do mar: 148 metros.", "Sítio Ramsar desde 2007.", "Mais de 200 espécies de aves registadas.", "O nível da água baixou 5 metros na década de 1980."],
      fr: ["Superficie du lac Dojran : 43,1 km² (total), dont 27,3 km² en Macédoine du Nord.", "Profondeur maximale : 10 mètres.", "Altitude au-dessus du niveau de la mer : 148 mètres.", "Site Ramsar depuis 2007.", "Plus de 200 espèces d'oiseaux recensées.", "Le niveau de l'eau a baissé de 5 mètres dans les années 1980."],
